--

CREATE FUNCTION public.random_birth_date(min_age integer DEFAULT 18, max_age integer DEFAULT 65) RETURNS timestamp without time zone
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN (CURRENT_DATE - (interval '1 day' * (365 * min_age + floor(random() * 365 * (max_age - min_age)))))::TIMESTAMP;
END;
$$;


