CREATE FUNCTION public.random_timestamp(start_date timestamp without time zone, end_date timestamp without time zone) RETURNS timestamp without time zone
    LANGUAGE plpgsql
    AS $$
BEGIN
    RETURN start_date + (random() * (extract(epoch from (end_date - start_date)))) * INTERVAL '1 second';
END;
$$;


