CREATE FUNCTION public.random_timestamp(start_date timestamp without time zone, end_date timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Calculate the difference between start and end dates in seconds
    RETURN start_date + (floor(random() * (EXTRACT(EPOCH FROM end_date - start_date))) * INTERVAL '1 second');
END;
$$;


