CREATE TABLE analytical_schema.fact_ukg_employee_job_history_details (
    employee_id character varying(50) NOT NULL,
    job_effective_date timestamp without time zone NOT NULL,
    reason_code character varying(50) NOT NULL,
    employee_head_count_fytd integer,
    number_of_hires integer,
    number_of_interns integer,
    number_of_terminations integer,
    turnover double precision
);


ALTER TABLE analytical_schema.fact_ukg_employee_job_history_details OWNER TO postgres;

--
-- Name: vw_monthly_turnover_metrics; Type: VIEW; Schema: analytical_schema; Owner: postgres
--

CREATE VIEW analytical_schema.vw_monthly_turnover_metrics AS
 SELECT date_trunc('month'::text, job_effective_date) AS month,
    sum(number_of_hires) AS total_hires,
    sum(number_of_interns) AS total_interns,
    sum(number_of_terminations) AS total_terminations,
    avg(turnover) AS avg_turnover_rate,
    max(employee_head_count_fytd) AS max_headcount
   FROM analytical_schema.fact_ukg_employee_job_history_details
  WHERE ((employee_id)::text ~~ 'AGG%'::text)
  GROUP BY (date_trunc('month'::text, job_effective_date))
  ORDER BY (date_trunc('month'::text, job_effective_date));


ALTER VIEW analytical_schema.vw_monthly_turnover_metrics OWNER TO postgres;

